"""Deterministic post-case debrief evaluation — generated by the Python core.

``SimulationOrchestrator.build_evaluation()`` is the single source of truth
for the Debrief tab. These tests lock in the contract:

1. The payload is present on completion AND on death (server responses and
   ``get_state()``), with the full schema and ``generated_by: scrubin-core``.
2. Identical play ⇒ byte-identical evaluation (determinism).
3. Perfect play scores high and reports no mistakes; death reports a FATAL
   critical event, a "Deceased" outcome, and a rock-bottom safety score.
4. Reported stock steps (correct via /next, wrong via /complicate) actually
   shape the report — mistakes appear and competency drops.
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

import pytest

from scrubin_core_engine import SimulationOrchestrator
from scrubin_core_procedures import ALL_PROCEDURES

EVAL_KEYS = {
    "final_score",
    "competency_score",
    "safety_score",
    "efficiency_score",
    "patient_outcome",
    "timeline_summary",
    "critical_events",
    "mistakes",
    "strengths",
    "recommendations",
    "generated_by",
}

SEEDS = [7, 42, 123]


def correct_option(decision, active_comp):
    for opt in decision.get("options", []):
        if active_comp in (opt.get("correctForComplications") or []):
            return opt["id"]
    for opt in decision.get("options", []):
        if opt.get("correctForComplications"):
            return opt["id"]
    return None


def stock_run(seed, pid, wrong_indices=()):
    """Drive a full stock run the way the client does: report correct steps
    via /next, wrong steps via /complicate (step is skipped, matching the
    client), and rescue every crisis with the correct intervention."""
    orch = SimulationOrchestrator(seed, pid)
    total = orch.procedure["totalTicks"]
    idx = 0
    guard = 0
    while not orch.completed and guard < 500:
        guard += 1
        if orch.mode == "branched":
            d = orch.pending_decision
            if not d:
                orch.next()
                continue
            opt = correct_option(d, orch.active_complication)
            if opt is None:
                break
            orch.submit_decision(d["id"], opt)
            continue
        if idx >= total:
            break
        correct = idx not in wrong_indices
        if correct:
            orch.record_stock_step(idx, True, f"Step {idx + 1}")
            orch.next()
            idx += 1
        else:
            # The engine records the failed step itself (mirroring /complicate).
            # Mistake complications skip the failed step (client behavior).
            orch.trigger_complication(orch.procedure["allowedComplications"][0], idx, f"Step {idx + 1}")
            idx += 1
    if orch.mode != "deceased":
        orch.completed = True
        orch.mode = "stock"
    return orch


def neglect_to_death(seed, pid):
    """Let an untended complication kill the patient (critical tier)."""
    orch = SimulationOrchestrator(seed, pid)
    guard = 0
    while not orch.completed and guard < 600:
        guard += 1
        if orch.mode == "branched":
            for _ in range(12):
                if orch.completed:
                    break
                orch.tick_vitals_only()
            continue
        orch.next()
    return orch


# ─────────────────────────────────────────────────────────────────────────────
# Schema + determinism
# ─────────────────────────────────────────────────────────────────────────────

def test_evaluation_schema_on_completion():
    orch = stock_run(7, "appendectomy")
    ev = orch.build_evaluation()
    assert set(ev.keys()) == EVAL_KEYS
    assert ev["generated_by"] == "scrubin-core"
    for k in ("final_score", "competency_score", "safety_score", "efficiency_score"):
        assert isinstance(ev[k], int) and 0 <= ev[k] <= 100, k
    assert isinstance(ev["patient_outcome"], str)
    for key in ("timeline_summary", "critical_events", "mistakes", "strengths", "recommendations"):
        assert isinstance(ev[key], list), key


@pytest.mark.parametrize("pid", ["appendectomy", "whipple", "exploratory-laparotomy"])
def test_evaluation_is_deterministic(pid):
    a = stock_run(7, pid).build_evaluation()
    b = stock_run(7, pid).build_evaluation()
    assert a == b


def test_evaluation_deterministic_across_seeds_shape():
    """Different seeds produce valid (not necessarily equal) evaluations."""
    for seed in SEEDS:
        ev = stock_run(seed, "appendectomy").build_evaluation()
        assert set(ev.keys()) == EVAL_KEYS
        assert ev["generated_by"] == "scrubin-core"


# ─────────────────────────────────────────────────────────────────────────────
# Perfect play
# ─────────────────────────────────────────────────────────────────────────────

def test_perfect_play_scores_and_no_mistakes():
    orch = stock_run(7, "appendectomy")
    ev = orch.build_evaluation()
    assert ev["final_score"] >= 85, ev
    assert ev["competency_score"] >= 90, ev
    assert ev["safety_score"] >= 85, ev
    assert ev["efficiency_score"] >= 90, ev
    assert ev["mistakes"] == [], ev["mistakes"]
    assert ev["patient_outcome"] == "Stable / Discharged", ev["patient_outcome"]
    # No surgical-error or fatal critical events in a clean run.
    severities = {c["severity"] for c in ev["critical_events"]}
    assert severities <= {"DETERIORATION"}, severities
    assert len(ev["strengths"]) > 0


# ─────────────────────────────────────────────────────────────────────────────
# Death
# ─────────────────────────────────────────────────────────────────────────────

def test_death_evaluation_payload():
    orch = neglect_to_death(7, "exploratory-laparotomy")
    assert orch.mode == "deceased" and orch.completed
    ev = orch.build_evaluation()
    assert ev["patient_outcome"] == "Deceased"
    assert ev["safety_score"] == 12
    assert ev["final_score"] < 40
    assert any(c["severity"] == "FATAL" for c in ev["critical_events"])
    assert any("Patient died" in c["description"] for c in ev["critical_events"])
    assert any("died" in t["description"].lower() for t in ev["timeline_summary"])
    assert ev["critical_events"][-1]["severity"] == "FATAL"
    # Death always generates a debrief recommendation.
    assert any("post-mortem" in r["description"].lower() for r in ev["recommendations"])


# ─────────────────────────────────────────────────────────────────────────────
# Reported stock steps shape the report
# ─────────────────────────────────────────────────────────────────────────────

def test_wrong_steps_appear_in_mistakes_and_lower_competency():
    clean = stock_run(7, "appendectomy")
    flawed = stock_run(7, "appendectomy", wrong_indices=(3, 8))
    assert clean.build_evaluation()["mistakes"] == []
    ev = flawed.build_evaluation()
    assert len(ev["mistakes"]) >= 2, ev["mistakes"]
    labels = " ".join(m["description"].lower() for m in ev["mistakes"])
    assert "step 4" in labels and "step 9" in labels, labels
    assert ev["competency_score"] < clean.build_evaluation()["competency_score"]
    # Complication history recorded the mistake source.
    state = flawed.get_state()
    assert state["correctSteps"] == 28 and state["totalSteps"] == 30
    assert sum(1 for c in state["complicationHistory"] if c["source"] == "mistake") >= 2


def test_stock_history_visible_in_state():
    orch = stock_run(7, "appendectomy")
    state = orch.get_state()
    assert state["totalSteps"] == orch.procedure["totalTicks"] == 30
    assert state["correctSteps"] == 30
    assert len(state["stockHistory"]) == 30
    assert state["evaluation"] is not None
    assert state["evaluation"]["generated_by"] == "scrubin-core"


# ─────────────────────────────────────────────────────────────────────────────
# API surface (FastAPI shim)
# ─────────────────────────────────────────────────────────────────────────────

@pytest.fixture(scope="module")
def api_client():
    from fastapi.testclient import TestClient
    from server import app
    return TestClient(app)


def test_api_complete_returns_evaluation(api_client):
    r = api_client.post("/start", json={"procedure": "appendectomy", "seed": 7})
    assert r.status_code == 200
    sid = r.json()["session_id"]
    for i in range(3):
        r = api_client.post(
            "/next",
            json={"session_id": sid, "step_index": i, "step_correct": True, "step_label": f"Step {i + 1}"},
        )
        assert r.status_code == 200
    r = api_client.post("/complete", json={"session_id": sid})
    assert r.status_code == 200
    data = r.json()
    assert data["completed"] is True
    ev = data["evaluation"]
    assert ev is not None and ev["generated_by"] == "scrubin-core"
    assert data["total_steps"] == 3 and data["correct_steps"] == 3


def test_api_death_returns_evaluation(api_client):
    proc = next(p for p in ALL_PROCEDURES if p["id"] == "exploratory-laparotomy")
    comp = proc["allowedComplications"][0]
    r = api_client.post("/start", json={"procedure": "exploratory-laparotomy", "seed": 7})
    assert r.status_code == 200
    sid = r.json()["session_id"]
    r = api_client.post("/next", json={"session_id": sid, "step_index": 0, "step_correct": True, "step_label": "Step 1"})
    assert r.status_code == 200
    r = api_client.post("/complicate", json={"session_id": sid, "complication": comp, "step_index": 1, "step_label": "Step 2"})
    assert r.status_code == 200
    ev = None
    for _ in range(300):
        r = api_client.post("/tick", json={"session_id": sid})
        assert r.status_code == 200
        if r.json()["completed"]:
            ev = r.json()["evaluation"]
            break
    assert ev is not None, "patient never died under neglect"
    assert ev["patient_outcome"] == "Deceased"


# ─────────────────────────────────────────────────────────────────────────────
# /complete honors a death (regression: mode was normalized to "stock"
# before the evaluation was built, so the death caps never applied — dead
# patients got efficiency 100 and inflated finals)
# ─────────────────────────────────────────────────────────────────────────────

def test_api_complete_applies_death_caps_when_session_died(api_client):
    """A session that dies must still be debriefed as a death by /complete.

    Regression for the bug where /complete forced mode="stock" before
    building the evaluation: build_evaluation()'s is_deceased check never
    fired, so dead patients were reported as "Stabilized / Transferred"
    with efficiency 100. Death caps: safety == 12, efficiency <= 40,
    competency <= 45, final < 40."""
    proc = next(p for p in ALL_PROCEDURES if p["id"] == "exploratory-laparotomy")
    comp = proc["allowedComplications"][0]
    r = api_client.post("/start", json={"procedure": "exploratory-laparotomy", "seed": 7})
    assert r.status_code == 200
    sid = r.json()["session_id"]
    r = api_client.post("/next", json={"session_id": sid, "step_index": 0, "step_correct": True, "step_label": "Step 1"})
    assert r.status_code == 200
    r = api_client.post("/complicate", json={"session_id": sid, "complication": comp, "step_index": 1, "step_label": "Step 2"})
    assert r.status_code == 200

    # Neglect the complication until the patient dies (same driver as
    # test_api_death_returns_evaluation).
    died = False
    for _ in range(300):
        r = api_client.post("/tick", json={"session_id": sid})
        assert r.status_code == 200
        if r.json()["completed"]:
            died = True
            break
    assert died, "patient never died under neglect"

    # The regression: /complete must still apply the death caps.
    r = api_client.post("/complete", json={"session_id": sid})
    assert r.status_code == 200
    data = r.json()
    assert data["completed"] is True
    ev = data["evaluation"]
    assert ev is not None and ev["generated_by"] == "scrubin-core"
    assert ev["patient_outcome"] == "Deceased", ev["patient_outcome"]
    assert ev["safety_score"] == 12, ev
    assert ev["efficiency_score"] <= 40, ev
    assert ev["competency_score"] <= 45, ev
    assert ev["final_score"] < 40, ev
    assert any(c["severity"] == "FATAL" for c in ev["critical_events"])


def test_api_complete_does_not_cap_a_survivor(api_client):
    """The death caps must not leak into non-death debriefs (guard against
    an over-broad fix). A clean completed case keeps normal scores."""
    r = api_client.post("/start", json={"procedure": "appendectomy", "seed": 7})
    assert r.status_code == 200
    sid = r.json()["session_id"]
    for i in range(3):
        r = api_client.post(
            "/next",
            json={"session_id": sid, "step_index": i, "step_correct": True, "step_label": f"Step {i + 1}"},
        )
        assert r.status_code == 200
    r = api_client.post("/complete", json={"session_id": sid})
    assert r.status_code == 200
    ev = r.json()["evaluation"]
    assert ev is not None
    assert ev["patient_outcome"] != "Deceased"
    assert ev["efficiency_score"] > 40, ev
    assert ev["safety_score"] > 12, ev


def test_complete_session_normalization_contract():
    """Session-level contract: finish_with_evaluation captures the terminal
    state before normalizing mode, so the evaluation sees the death even
    though the returned payload carries a neutral stock mode."""
    from scrubin_core_engine import SimulationSession, SessionManager

    manager = SessionManager()
    session = manager.create("unit-death", 7, "exploratory-laparotomy")
    orch = session.orchestrator
    # Deterministic death: the orchestrator is in deceased mode already.
    orch.mode = "deceased"
    orch.completed = True
    orch.death_reason = "Test death"

    state = session.finish_with_evaluation(deceased=True)
    # The payload is normalized for the UI...
    assert state["mode"] == "stock"
    assert state["completed"] is True
    # ...but the evaluation reflects the death.
    ev = state["evaluation"]
    assert ev is not None
    assert ev["patient_outcome"] == "Deceased"
    assert ev["safety_score"] == 12
    assert ev["efficiency_score"] <= 40
    assert ev["competency_score"] <= 45

    # And a fresh call with deceased=False must not cap.
    session2 = manager.create("unit-survivor", 7, "appendectomy")
    state2 = session2.finish_with_evaluation(deceased=False)
    ev2 = state2["evaluation"]
    assert ev2["patient_outcome"] != "Deceased"
    assert ev2["efficiency_score"] > 40
    assert ev2["safety_score"] > 12


# ─────────────────────────────────────────────────────────────────────────────
# Efficiency must penalize crisis drag (fast clicking cannot buy efficiency
# out of a prolonged or unresolved complication)
# ─────────────────────────────────────────────────────────────────────────────

def test_efficiency_penalized_per_tick_in_active_complication():
    """Each tick spent with an unresolved complication active must deduct
    from the efficiency score (3.5 pts per crisis tick)."""
    orch = stock_run(7, "appendectomy")
    clean = orch.build_evaluation()

    # Simulate a crisis that dragged on: same case, but with 6 ticks spent
    # in an active complication. Everything else is identical.
    orch._ticks_in_active_complication = 6
    dragged = orch.build_evaluation()

    expected_drop = 3.5 * 6  # 21 pts
    assert clean["efficiency_score"] - dragged["efficiency_score"] >= expected_drop - 1, (
        clean["efficiency_score"], dragged["efficiency_score"]
    )
    assert dragged["efficiency_score"] <= clean["efficiency_score"], dragged


def test_efficiency_capped_when_case_ends_with_unresolved_complication():
    """Ending the case with a complication still unresolved caps efficiency
    at 40 (like a death) — the patient leaves the OR unstable."""
    orch = SimulationOrchestrator(7, "appendectomy")
    # Drive to the final tick, rescuing any spontaneous crises cleanly (the
    # same pattern as stock_run) so the case is otherwise perfect.
    total = orch.procedure["totalTicks"]
    idx = 0
    guard = 0
    while not orch.completed and guard < 500:
        guard += 1
        if orch.mode == "branched":
            d = orch.pending_decision
            if not d:
                orch.next()
                continue
            opt = correct_option(d, orch.active_complication)
            if opt is None:
                break
            orch.submit_decision(d["id"], opt)
            continue
        if idx >= total:
            break
        orch.record_stock_step(idx, True, f"Step {idx + 1}")
        orch.next()
        idx += 1
    # Re-enter a crisis at the very end: a mistake complication stays open.
    orch.trigger_complication(orch.procedure["allowedComplications"][0], total, "Final step")
    orch.completed = True
    # No decision was submitted, so the complication history entry is unresolved.
    assert any(not c.get("resolved") for c in orch.complication_history)

    ev = orch.build_evaluation()
    assert ev["patient_outcome"] != "Deceased"
    assert ev["efficiency_score"] <= 40, ev
